-- Thirty replay-safe, choice-driven life-event scenes.
-- Every action has at least three server-only outcomes. `weight` is relative;
-- `delta` is applied after an optional integer `multiplier` percentage.

insert into life_event_scenes (key, audience, title, prompt, emoji, choices, sort_order) values
('all_last_bus','all','末班车刚刚开走','你站在陌生的站牌下，手机只剩 8% 电。今晚要怎么回去？','🚌',
$j$[{"key":"walk","label":"沿着地图走回去","outcomes":[{"key":"shortcut","label":"发现一条漂亮的河边近路","detail":"夜风很冷，但这段路意外治愈。","delta":6,"weight":30,"tone":"good"},{"key":"longway","label":"地图把你带进了住宅区","detail":"多走了四十分钟，好在平安到家。","delta":-3,"weight":45,"tone":"neutral"},{"key":"battery","label":"手机半路没电","detail":"你凭记忆绕了很久，终于看到熟悉的灯。","delta":-6,"weight":25,"tone":"bad"}]},{"key":"ask","label":"向同站的人求助","outcomes":[{"key":"shared_taxi","label":"几个人一起拼车","detail":"车费不贵，还认识了新朋友。","delta":6,"weight":35,"tone":"good"},{"key":"wrong_bus","label":"热心建议却指错方向","detail":"你又换了两次车才到家。","delta":-3,"weight":30,"tone":"bad"},{"key":"lift","label":"碰巧遇到顺路的人","detail":"一场狼狈变成了一段好故事。","delta":9,"weight":35,"tone":"good"}]}]$j$::jsonb,1),
('all_free_day','all','日历突然空出一天','原本安排满满的一天被临时取消。你决定怎样使用这份意外的空白？','☀️',
$j$[{"key":"rest","label":"关掉闹钟彻底休息","outcomes":[{"key":"recharged","label":"真正睡饱了","detail":"醒来时脑袋久违地清晰。","delta":6,"weight":45,"tone":"good"},{"key":"overslept","label":"一觉睡到天黑","detail":"身体休息了，心里却有点空落。","delta":0,"weight":35,"tone":"neutral"},{"key":"noise","label":"邻居从早装修到晚","detail":"计划中的安静一天彻底泡汤。","delta":-3,"weight":20,"tone":"bad"}]},{"key":"explore","label":"随便坐一班车去看看","outcomes":[{"key":"market","label":"撞见一场周末市集","detail":"你带着便宜又喜欢的小物回家。","delta":9,"weight":30,"tone":"good"},{"key":"rain","label":"刚下车就下大雨","detail":"没看到风景，只买到一把昂贵的伞。","delta":-3,"weight":35,"tone":"bad"},{"key":"cafe","label":"找到一家安静的小店","detail":"你在那里写下了接下来想做的事。","delta":6,"weight":35,"tone":"good"}]}]$j$::jsonb,2),
('all_fridge','all','合租冰箱危机','你打开冰箱，发现自己留到今天的那份甜点不见了。','🍰',
$j$[{"key":"message","label":"在群里直接问清楚","outcomes":[{"key":"apology","label":"室友立刻道歉并补买","detail":"误会没有发酵，冰箱里还多了一份。","delta":6,"weight":40,"tone":"good"},{"key":"silence","label":"群里突然一片安静","detail":"甜点没回来，气氛也变得微妙。","delta":-3,"weight":35,"tone":"bad"},{"key":"yourself","label":"原来是你昨晚吃掉了","detail":"聊天记录提醒了你，尴尬但很好笑。","delta":0,"weight":25,"tone":"neutral"}]},{"key":"letgo","label":"算了，重新买一份","outcomes":[{"key":"discount","label":"正好遇到买一送一","detail":"损失被小小的好运补上。","delta":6,"weight":30,"tone":"good"},{"key":"soldout","label":"喜欢的口味售罄","detail":"你拎着替代品回家，还是有点遗憾。","delta":-3,"weight":40,"tone":"bad"},{"key":"note","label":"室友留下了道歉纸条","detail":"新甜点已经在门口等你。","delta":9,"weight":30,"tone":"good"}]}]$j$::jsonb,3),
('all_unknown_call','all','陌生号码打来','一个陌生号码连续打了三次。屏幕再次亮起时，你会怎么做？','📞',
$j$[{"key":"answer","label":"接起来听听","outcomes":[{"key":"offer","label":"是期待已久的好消息","detail":"对方确认了一次难得的机会。","delta":9,"weight":30,"tone":"good"},{"key":"survey","label":"是很长的推销电话","detail":"你礼貌听了五分钟才脱身。","delta":-3,"weight":45,"tone":"bad"},{"key":"parcel","label":"快递员正站在门外","detail":"差一点就错过重要包裹。","delta":3,"weight":25,"tone":"good"}]},{"key":"ignore","label":"静音，等对方留言","outcomes":[{"key":"voicemail","label":"重要信息完整留在语音里","detail":"你按自己的节奏处理，没有错过什么。","delta":6,"weight":40,"tone":"good"},{"key":"deadline","label":"对方没有留言","detail":"后来才知道回复时限已经过去。","delta":-6,"weight":25,"tone":"bad"},{"key":"scam","label":"系统标记为诈骗号码","detail":"谨慎替你省下一场麻烦。","delta":3,"weight":35,"tone":"good"}]}]$j$::jsonb,4),
('all_wallet','all','长椅下的钱包','你在公园长椅下发现一个装着现金和证件的钱包。','👛',
$j$[{"key":"police","label":"交到附近服务台","outcomes":[{"key":"thanks","label":"失主很快赶来","detail":"一句真诚的感谢让你开心了很久。","delta":9,"weight":40,"tone":"good"},{"key":"paperwork","label":"登记过程比想象中麻烦","detail":"你花掉不少时间，但还是放心了。","delta":0,"weight":40,"tone":"neutral"},{"key":"closed","label":"服务台已经下班","detail":"你只好第二天再跑一趟。","delta":-3,"weight":20,"tone":"bad"}]},{"key":"contact","label":"按证件线索自己联系失主","outcomes":[{"key":"coffee","label":"失主请你喝咖啡","detail":"你们聊得投缘，成了偶尔联系的朋友。","delta":9,"weight":35,"tone":"good"},{"key":"suspicious","label":"对方一开始以为是骗局","detail":"解释了很久，最后总算说清楚。","delta":-3,"weight":30,"tone":"bad"},{"key":"family","label":"接电话的是焦急的家人","detail":"你及时送回了他们急需的证件。","delta":6,"weight":35,"tone":"good"}]}]$j$::jsonb,5),
('all_rain_invite','all','暴雨里的邀约','朋友临时约你去一个只听过名字的聚会，窗外的雨越来越大。','🌧️',
$j$[{"key":"go","label":"穿上外套还是出门","outcomes":[{"key":"connection","label":"遇见很合拍的人","detail":"雨声成了那晚最好的背景音乐。","delta":9,"weight":35,"tone":"good"},{"key":"soaked","label":"全程湿着鞋子","detail":"聚会普通，回家后还感冒了两天。","delta":-6,"weight":25,"tone":"bad"},{"key":"quiet","label":"人不多但聊得很深","detail":"你听到一个正好需要的故事。","delta":6,"weight":40,"tone":"good"}]},{"key":"stay","label":"婉拒，留在家里","outcomes":[{"key":"cozy","label":"度过安稳的一晚","detail":"热饮、电影和雨声都刚刚好。","delta":6,"weight":40,"tone":"good"},{"key":"fomo","label":"群聊照片刷了一整晚","detail":"你开始怀疑自己错过了什么。","delta":-3,"weight":35,"tone":"bad"},{"key":"cancelled","label":"聚会后来因天气取消","detail":"你的决定突然显得非常明智。","delta":3,"weight":25,"tone":"good"}]}]$j$::jsonb,6),
('all_file_crash','all','截止日前文件损坏','提交前十分钟，电脑提示文件无法打开。','💻',
$j$[{"key":"recover","label":"立刻寻找自动备份","outcomes":[{"key":"full","label":"云端保存了完整版本","detail":"你在最后一分钟顺利提交。","delta":9,"weight":35,"tone":"good"},{"key":"old","label":"只找到两小时前的版本","detail":"关键内容要重写，但至少不是从零开始。","delta":-3,"weight":45,"tone":"neutral"},{"key":"none","label":"所有备份都失效","detail":"你只能提交一份仓促重建的文件。","delta":-6,"weight":20,"tone":"bad"}]},{"key":"contact","label":"先联系负责人说明情况","outcomes":[{"key":"extension","label":"获得一次短暂延期","detail":"坦诚沟通换来足够的补救时间。","delta":6,"weight":40,"tone":"good"},{"key":"strict","label":"对方坚持原截止时间","detail":"解释没有改变规则，只剩下快速重做。","delta":-3,"weight":35,"tone":"bad"},{"key":"template","label":"对方发来可恢复模板","detail":"意外的帮助让你赶上了提交。","delta":9,"weight":25,"tone":"good"}]}]$j$::jsonb,7),
('all_refund','all','账户里多了一笔退款','你收到一笔不记得申请过的退款，备注也很模糊。','💷',
$j$[{"key":"check","label":"联系平台确认来源","outcomes":[{"key":"legit","label":"确实是延迟退款","detail":"这笔钱来得晚，却来得正是时候。","delta":6,"weight":45,"tone":"good"},{"key":"error","label":"平台发现了系统错误","detail":"钱被收回，但你避开了后续麻烦。","delta":0,"weight":35,"tone":"neutral"},{"key":"hours","label":"客服让你转接了四次","detail":"问题解决了，半天也过去了。","delta":-3,"weight":20,"tone":"bad"}]},{"key":"wait","label":"先不动这笔钱，观察几天","outcomes":[{"key":"confirmed","label":"几天后收到正式说明","detail":"谨慎没有成本，退款也正式属于你。","delta":6,"weight":40,"tone":"good"},{"key":"reversed","label":"金额自动撤回","detail":"没有损失，也没有惊喜。","delta":0,"weight":40,"tone":"neutral"},{"key":"fee","label":"账户同时扣了一笔隐藏费用","detail":"数字游戏最终让你小亏一笔。","delta":-3,"weight":20,"tone":"bad"}]}]$j$::jsonb,8),
('all_social_mixup','all','群聊里的一句误会','你发的一句话被截掉上下文转进另一个群，气氛开始不对。','💬',
$j$[{"key":"explain","label":"马上公开补全上下文","outcomes":[{"key":"cleared","label":"大家很快理解了","detail":"误会散去，甚至有人替你缓和气氛。","delta":6,"weight":45,"tone":"good"},{"key":"debate","label":"解释引出更长的争论","detail":"越说越多，真正的问题反而模糊。","delta":-3,"weight":35,"tone":"bad"},{"key":"apology","label":"你发现确实表达得不妥","detail":"一次具体道歉让关系重新落地。","delta":3,"weight":20,"tone":"neutral"}]},{"key":"private","label":"私下联系最在意的人","outcomes":[{"key":"honest","label":"对方愿意坦白感受","detail":"你们谈清了比这句话更深的问题。","delta":9,"weight":35,"tone":"good"},{"key":"seen","label":"消息已读但没有回复","detail":"沉默比争论更让人不安。","delta":-6,"weight":25,"tone":"bad"},{"key":"joke","label":"原来对方根本没当真","detail":"你松了一口气，也学会少脑补一点。","delta":3,"weight":40,"tone":"good"}]}]$j$::jsonb,9),
('all_stage','all','临时被点名上台','主持人说下一位分享者没来，希望你马上顶上五分钟。','🎤',
$j$[{"key":"accept","label":"深呼吸，接过麦克风","outcomes":[{"key":"applause","label":"现场反应超出预期","detail":"你说的一个小故事打动了很多人。","delta":9,"weight":30,"tone":"good"},{"key":"blank","label":"讲到一半突然忘词","detail":"停顿很长，但你还是把最后一句说完了。","delta":-3,"weight":30,"tone":"bad"},{"key":"natural","label":"没有完美，却很真诚","detail":"有人在结束后专门来向你道谢。","delta":6,"weight":40,"tone":"good"}]},{"key":"decline","label":"说明自己没有准备好","outcomes":[{"key":"respected","label":"主持人理解并迅速调整","detail":"边界被尊重，你也没有因此被责怪。","delta":3,"weight":45,"tone":"neutral"},{"key":"regret","label":"后来发现这是难得机会","detail":"你在台下反复想象如果答应会怎样。","delta":-3,"weight":35,"tone":"bad"},{"key":"support","label":"你改为帮下一位整理内容","detail":"没有站到台前，却让整段流程顺利完成。","delta":6,"weight":20,"tone":"good"}]}]$j$::jsonb,10),
('all_old_friend','all','旧朋友突然来访','一位很久没见的朋友说今晚刚好经过你的城市，只能停留两个小时。','🚆',
$j$[{"key":"meet","label":"放下计划去见面","outcomes":[{"key":"warm","label":"像从未分开过一样","detail":"两小时把很多旧日快乐重新点亮。","delta":9,"weight":40,"tone":"good"},{"key":"distant","label":"彼此都变了很多","detail":"谈话礼貌，却再也找不到从前的节奏。","delta":-3,"weight":30,"tone":"neutral"},{"key":"honest","label":"终于说开一件旧事","detail":"迟来的坦白让你们都轻松了一点。","delta":6,"weight":30,"tone":"good"}]},{"key":"reschedule","label":"改约下一次更充裕的见面","outcomes":[{"key":"booked","label":"你们真的订好了日期","detail":"期待让这次错过变得可以接受。","delta":6,"weight":35,"tone":"good"},{"key":"drift","label":"下一次一直没有发生","detail":"聊天框慢慢又沉到了最下面。","delta":-6,"weight":30,"tone":"bad"},{"key":"call","label":"当晚改成一次长电话","detail":"没有面对面，却聊得比预想更深。","delta":3,"weight":35,"tone":"good"}]}]$j$::jsonb,11),
('all_crossroads','all','两个都不错的未来','你同时收到两个机会：一个稳定熟悉，一个未知但很想尝试。','🧭',
$j$[{"key":"stable","label":"选择更确定的那条路","outcomes":[{"key":"grow","label":"稳定里出现新的成长","detail":"原来安全感也能为冒险留出空间。","delta":9,"weight":30,"tone":"good"},{"key":"calm","label":"生活平稳地向前","detail":"没有戏剧性，但你终于睡得踏实。","delta":3,"weight":45,"tone":"neutral"},{"key":"whatif","label":"你开始频繁想起另一条路","detail":"得到安稳的同时，也多了一个如果。","delta":-3,"weight":25,"tone":"bad"}]},{"key":"unknown","label":"选择更未知的那条路","outcomes":[{"key":"breakthrough","label":"陌生环境打开新世界","detail":"最初的不安变成了久违的兴奋。","delta":9,"weight":35,"tone":"good"},{"key":"hard","label":"现实比想象中艰难","detail":"你付出很多，暂时还看不到回报。","delta":-6,"weight":30,"tone":"bad"},{"key":"detour","label":"它不是终点，却是重要绕路","detail":"你没有得到预期结果，却更了解自己。","delta":3,"weight":35,"tone":"neutral"}]}]$j$::jsonb,12),

('solo_weekend','solo','一个人的周末','周末没有任何人有空，你拥有整整两天只属于自己的时间。','🎧',
$j$[{"key":"plan","label":"给自己安排一场约会","outcomes":[{"key":"cinema","label":"包场般看完一部好电影","detail":"一个人并没有减少快乐。","delta":9,"weight":35,"tone":"good"},{"key":"crowd","label":"想去的地方全都排长队","detail":"计划被人潮打散，只好提前回家。","delta":-3,"weight":30,"tone":"bad"},{"key":"discover","label":"偶然发现新的兴趣","detail":"这一天后来成了长期爱好的开始。","delta":6,"weight":35,"tone":"good"}]},{"key":"open","label":"不做计划，看看会发生什么","outcomes":[{"key":"neighbor","label":"被邻居临时邀请吃饭","detail":"原本空白的晚上突然很热闹。","delta":6,"weight":30,"tone":"good"},{"key":"scroll","label":"两天在刷手机中溜走","detail":"没有休息好，也没留下什么记忆。","delta":-6,"weight":35,"tone":"bad"},{"key":"quiet","label":"慢慢整理好自己的房间","detail":"安静却踏实，生活重新有了秩序。","delta":3,"weight":35,"tone":"neutral"}]}]$j$::jsonb,101),
