('solo_last_ticket','solo','只剩最后一张票','售票窗口只剩一张今晚的演出票，没有同伴能一起去。','🎟️',
$j$[{"key":"buy","label":"买下，一个人进场","outcomes":[{"key":"front","label":"临时被升级到好座位","detail":"舞台近得像专门为你演出。","delta":9,"weight":30,"tone":"good"},{"key":"awkward","label":"左右都是热闹的朋友群","detail":"表演不错，但你始终有点不自在。","delta":-3,"weight":30,"tone":"bad"},{"key":"fan","label":"和旁边同好聊了一晚","detail":"你们约好下次还来看。","delta":6,"weight":40,"tone":"good"}]},{"key":"leave","label":"把票留给更想去的人","outcomes":[{"key":"gift","label":"买票的人送你一张周边","detail":"一次让步换回意外的善意。","delta":6,"weight":30,"tone":"good"},{"key":"regret","label":"演出后来成了热门话题","detail":"你刷到视频时还是有点后悔。","delta":-3,"weight":45,"tone":"bad"},{"key":"other","label":"你改去了一场免费活动","detail":"没有原计划精彩，却认识了有趣的人。","delta":3,"weight":25,"tone":"neutral"}]}]$j$::jsonb,103),
