$j$[{"key":"rush","label":"抓起东西立刻冲出去","outcomes":[{"key":"justin","label":"最后一分钟赶到","detail":"狼狈是真的，机会也保住了。","delta":6,"weight":40,"tone":"good"},{"key":"forgot","label":"到门口才发现忘带材料","detail":"速度没能弥补准备的缺口。","delta":-6,"weight":30,"tone":"bad"},{"key":"delay","label":"活动本身也临时延迟","detail":"命运替你争取了二十分钟。","delta":9,"weight":30,"tone":"good"}]},{"key":"call","label":"先打电话诚实说明","outcomes":[{"key":"online","label":"对方允许改为线上参加","detail":"及时沟通保住了完整机会。","delta":9,"weight":35,"tone":"good"},{"key":"wait","label":"对方愿意等十分钟","detail":"你在压力里完成了一次有效沟通。","delta":6,"weight":35,"tone":"good"},{"key":"closed","label":"规则不接受迟到","detail":"今天只能变成一次昂贵的提醒。","delta":-6,"weight":30,"tone":"bad"}]}]$j$::jsonb,104),
('solo_blackout','solo','单人公寓突然停电','夜里整栋楼停电，你独自在房间，外面也没有明显动静。','🕯️',
$j$[{"key":"check","label":"带手电去楼道查看","outcomes":[{"key":"neighbors","label":"邻居们正一起找原因","detail":"大家分工，很快联系到物业。","delta":6,"weight":40,"tone":"good"},{"key":"stair","label":"在黑暗楼梯上崴到脚","detail":"问题没找到，行动还变得更慢。","delta":-6,"weight":20,"tone":"bad"},{"key":"switch","label":"只是自家保险开关跳闸","detail":"你第一次独立解决了这个问题。","delta":9,"weight":40,"tone":"good"}]},{"key":"wait","label":"留在房里等待恢复","outcomes":[{"key":"stars","label":"窗外的星星突然很清楚","detail":"没有电的半小时安静得难得。","delta":6,"weight":30,"tone":"good"},{"key":"long","label":"停电持续到凌晨","detail":"手机没电、冰箱也开始升温。","delta":-6,"weight":35,"tone":"bad"},{"key":"call","label":"一通久违的电话陪你等完","detail":"黑暗反而让一段关系重新连上。","delta":9,"weight":35,"tone":"good"}]}]$j$::jsonb,105),
('solo_interview','solo','独自坐在面试门外','候场区很安静，你听见前一位候选人回答得非常流利。','🪑',
