('duo_one_spot','duo','只剩一个名额','你和队友都想参加一个限定体验，但现场只剩最后一个位置。','☝️',
$j$[{"key":"decide","label":"用猜拳快速决定","outcomes":[{"key":"fair","label":"输赢都很爽快","detail":"一个人体验，另一个人负责拍下精彩瞬间。","delta":6,"weight":45,"tone":"good"},{"key":"rematch","label":"连续平局到工作人员催促","detail":"越想公平，场面反而越尴尬。","delta":-3,"weight":25,"tone":"bad"},{"key":"bonus","label":"工作人员临时挤出第二个名额","detail":"你们的默契坚持换来了双份好运。","delta":9,"weight":30,"tone":"good"}]},{"key":"give","label":"主动把名额让给队友","outcomes":[{"key":"return","label":"队友把纪念品送给你","detail":"没有亲自参加，却感到被认真记得。","delta":9,"weight":35,"tone":"good"},{"key":"normal","label":"队友开心地接受了","detail":"让步很平静，心里仍有一点点遗憾。","delta":0,"weight":40,"tone":"neutral"},{"key":"refuse","label":"你们互相谦让到名额过期","detail":"最后谁都没进去，只能一起笑自己。","delta":-3,"weight":25,"tone":"bad"}]}]$j$::jsonb,201),
('duo_low_mood','duo','队友突然安静下来','刚才还很投入的队友突然说“我没事”，却明显不太对劲。','🫂',
$j$[{"key":"ask","label":"停下来认真问一次","outcomes":[{"key":"open","label":"队友愿意说出原因","detail":"问题没有立刻消失，但彼此更靠近了。","delta":9,"weight":40,"tone":"good"},{"key":"space","label":"队友说现在不想谈","detail":"你的关心被看见，也需要一点空间。","delta":3,"weight":40,"tone":"neutral"},{"key":"snap","label":"对方把压力发泄在你身上","detail":"善意撞上坏时机，气氛变得紧绷。","delta":-6,"weight":20,"tone":"bad"}]},{"key":"continue","label":"先继续游戏，暗中照顾节奏","outcomes":[{"key":"recover","label":"队友慢慢找回状态","detail":"不追问也可以是一种体贴。","delta":6,"weight":40,"tone":"good"},{"key":"miss","label":"你忽略了对方真正的求助","detail":"结束后才知道，那一刻其实很重要。","delta":-6,"weight":25,"tone":"bad"},{"key":"laugh","label":"下个站点让两人一起笑起来","detail":"情绪没有被分析，却被温柔地接住。","delta":9,"weight":35,"tone":"good"}]}]$j$::jsonb,202),
('duo_menu','duo','双人默契菜单','你们必须背对背各选一道菜；选中同一道就有隐藏奖励。','🍜',
$j$[{"key":"favorite","label":"各自选自己最想吃的","outcomes":[{"key":"match","label":"答案完全一致","detail":"原来你们的默契藏在胃里。","delta":9,"weight":35,"tone":"good"},{"key":"different","label":"一个辣一个甜","detail":"完全不同，但正好可以交换着尝。","delta":3,"weight":45,"tone":"neutral"},{"key":"soldout","label":"两道菜都刚好售罄","detail":"默契还没验证，厨房先给了答案。","delta":-3,"weight":20,"tone":"bad"}]},{"key":"predict","label":"猜队友会选什么","outcomes":[{"key":"readmind","label":"你准确猜中了队友","detail":"对方惊讶得重新看了你一眼。","delta":9,"weight":30,"tone":"good"},{"key":"bothguess","label":"两人都放弃自己去猜对方","detail":"交叉错过，却成了最好笑的结果。","delta":3,"weight":45,"tone":"neutral"},{"key":"assume","label":"你的猜测和现实差很远","detail":"你发现自己其实还不够了解对方。","delta":-3,"weight":25,"tone":"bad"}]}]$j$::jsonb,203),
