$j$[{"key":"protect","label":"明确表示不方便代答","outcomes":[{"key":"trust","label":"队友知道后非常安心","detail":"一次小小守护让信任变得具体。","delta":9,"weight":45,"tone":"good"},{"key":"awkward","label":"打听的人觉得你太严肃","detail":"场面短暂尴尬，但边界守住了。","delta":0,"weight":35,"tone":"neutral"},{"key":"guess","label":"你的回避反而让人猜中了","detail":"没有说出口，信息却还是泄露了一点。","delta":-3,"weight":20,"tone":"bad"}]},{"key":"redirect","label":"用玩笑把话题带开","outcomes":[{"key":"smooth","label":"大家自然聊起别的事","detail":"没有冲突，也没有秘密受伤。","delta":6,"weight":45,"tone":"good"},{"key":"obvious","label":"玩笑显得太刻意","detail":"所有人都意识到这里真的有事。","delta":-3,"weight":30,"tone":"bad"},{"key":"teamwork","label":"队友顺势接住了话题","detail":"一个眼神就完成了默契配合。","delta":9,"weight":25,"tone":"good"}]}]$j$::jsonb,204),
('duo_budget','duo','两人预算突然缩水','你们为今天准备的钱只剩一半，但最期待的项目还没开始。','🧾',
$j$[{"key":"focus","label":"只保留最想做的一件事","outcomes":[{"key":"worth","label":"唯一项目非常值得","detail":"减少选择反而让体验更专注。","delta":9,"weight":35,"tone":"good"},{"key":"closed","label":"赶到时项目临时关闭","detail":"把希望押在一件事上，也承担了全部落空。","delta":-6,"weight":25,"tone":"bad"},{"key":"simple","label":"项目普通，但过程很开心","detail":"真正留下来的不是消费本身。","delta":6,"weight":40,"tone":"good"}]},{"key":"split","label":"各拿一半，各自自由使用","outcomes":[{"key":"same","label":"两人最后买了同样的东西","detail":"分开行动也没改变默契。","delta":6,"weight":30,"tone":"good"},{"key":"compare","label":"互相觉得对方花得不值","detail":"小预算引出了一场价值观辩论。","delta":-3,"weight":35,"tone":"bad"},{"key":"gift","label":"两人都偷偷给对方准备礼物","detail":"预算很少，惊喜却是双份。","delta":9,"weight":35,"tone":"good"}]}]$j$::jsonb,205),
